<#$\n.SYNOPSIS\n  Build and optionally push Docker images for all backend services and the frontend.\n\n.DESCRIPTION\n  This script builds Docker images for all service folders matching \"*-service\" under \"services/\" and for the frontend (\"frontend/\").\n  Images are tagged with the DockerHub user \"emeday17/\" and the provided tag. Optionally, images are pushed to DockerHub.\n\n.PARAMETER Tag\n  The image tag to apply to built images. Default: \"1.0.0\".\n\n.PARAMETER Push\n  If present, the script will `docker push` each built image after a successful build.\n\n.PARAMETER Services\n  Optional explicit list of service folder names to build (example: `iam-service`,`catalogo-service`).\n  If omitted, the script will auto-detect folders under `services/` that match `*-service`.\n\n.PARAMETER Frontend\n  If present, the script will build (and optionally push) the frontend image as well.\n\n.EXAMPLE\n  # Build all backend services and frontend (no push)\n  .\build-and-push.ps1 -Frontend\n\n  # Build and push all images with tag \"1.0.0\"\n  .\build-and-push.ps1 -Tag 1.0.0 -Push -Frontend\n#>\n\nparam(\n  [string]$Tag = \"1.0.0\",\n  [switch]$Push,\n  [string[]]$Services,\n  [switch]$Frontend\n)\n\n# Paths\n$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path\n$repoRoot = $scriptDir # Now at repo root\n$servicesPath = Join-Path $repoRoot 'services'\n$frontendPath = Join-Path $repoRoot 'frontend'\n\nWrite-Host \"Repo root: $repoRoot\"\nWrite-Host \"Services path: $servicesPath\"\nWrite-Host \"Frontend path: $frontendPath\"\n\n# Discover service directories if not provided\nif (-not $Services -or $Services.Count -eq 0) {\n    $serviceDirs = Get-ChildItem -Path $servicesPath -Directory | Where-Object { $_.Name -like '*-service' } | Select-Object -ExpandProperty Name\n} else {\n    $serviceDirs = $Services\n}\n\nif (-not $serviceDirs -or $serviceDirs.Count -eq 0) {\n    Write-Error \"No service directories found under $servicesPath.\"\n    exit 1\n}\n\n# Mapping for canonical image names\nfunction Get-ImageName($svcName) {\n    switch ($svcName) {\n        'iam-service' { return 'emeday17/iam-service' }\n        'catalogo-service' { return 'emeday17/eventos-catalogo' }\n        'proveedores-service' { return 'emeday17/eventos-proveedores' }\n        'contratacion-service' { return 'emeday17/eventos-contratacion' }\n        default { return \"emeday17/$svcName\" }\n    }\n}\n\nforeach ($svc in $serviceDirs) {\n    $dockerfile = Join-Path -Path $servicesPath -ChildPath \"$svc/Dockerfile\"\n    if (-not (Test-Path $dockerfile)) {\n      Write-Warning \"Skipping $($svc): Dockerfile not found at $dockerfile\"\n        continue\n    }\n\n    $imageName = Get-ImageName $svc\n    $fullTag = \"$($imageName):$Tag\"\n\n    Write-Host \"\nBuilding $fullTag from $dockerfile (context: $repoRoot)\" -ForegroundColor Cyan\n\n    $buildCmd = \"docker build -t $fullTag -f `\"$dockerfile`\" `\"$repoRoot`\"\"\n    Write-Host \"Running: $buildCmd\"\n    iex $buildCmd\n\n    if ($LASTEXITCODE -ne 0) {\n        Write-Error \"Build failed for $svc (exit $LASTEXITCODE). Aborting.\"\n        exit $LASTEXITCODE\n    }\n\n    if ($Push) {\n        Write-Host \"Pushing $fullTag\" -ForegroundColor Green\n        $pushCmd = \"docker push $fullTag\"\n        iex $pushCmd\n        if ($LASTEXITCODE -ne 0) {\n            Write-Error \"Push failed for $svc (exit $LASTEXITCODE). Aborting.\"\n            exit $LASTEXITCODE\n        }\n    }\n}\n\n# Build/push frontend if requested\nif ($Frontend) {\n    $frontendDockerfile = Join-Path $frontendPath 'Dockerfile'\n    if (-not (Test-Path $frontendDockerfile)) {\n        Write-Warning \"Skipping frontend: Dockerfile not found at $frontendDockerfile\"\n    } else {\n        $frontendImage = \"emeday17/eventos-frontend\"\n        $frontendTag = \"$frontendImage:$Tag\"\n        Write-Host \"\nBuilding $frontendTag from $frontendDockerfile (context: $frontendPath)\" -ForegroundColor Cyan\n        $buildCmd = \"docker build -t $frontendTag -f `\"$frontendDockerfile`\" `\"$frontendPath`\"\"\n        Write-Host \"Running: $buildCmd\"\n        iex $buildCmd\n        if ($LASTEXITCODE -ne 0) {\n            Write-Error \"Build failed for frontend (exit $LASTEXITCODE). Aborting.\"\n            exit $LASTEXITCODE\n        }\n        if ($Push) {\n            Write-Host \"Pushing $frontendTag\" -ForegroundColor Green\n            $pushCmd = \"docker push $frontendTag\"\n            iex $pushCmd\n            if ($LASTEXITCODE -ne 0) {\n                Write-Error \"Push failed for frontend (exit $LASTEXITCODE). Aborting.\"\n                exit $LASTEXITCODE\n            }\n        }\n    }\n}\n\nWrite-Host \"\nAll done.\" -ForegroundColor Green\n\nif ($Push) {\n    Write-Host \"Reminder: Ensure you are logged in to DockerHub (docker login) and have permissions to push to emeday17/* images.\" -ForegroundColor Yellow\n}\n